insert into public.product_translations (product_id, locale, name, description)
values
  ('20000000-0000-0000-0000-000000000001', 'ar', 'كوكيز الشوكولاتة الفاخرة', 'لعشاق الشوكولاتة الحقيقيين، كوكيز جولد محشوة بشوكولاتة لونا ومحضرة من الكاكاو وزبدة الكاكاو بمذاق غني وفاخر.'),
  ('20000000-0000-0000-0000-000000000001', 'en', 'Luxury Chocolate Cookies', 'For true chocolate lovers, Gold Cookies loaded with double Luna chocolate, cocoa, and cocoa butter for a deep, rich, luxurious taste.'),
  ('20000000-0000-0000-0000-000000000001', 'it', 'Biscotti al cioccolato di lusso', 'Per gli amanti del cioccolato: biscotti Gold con doppio cioccolato Luna, cacao e burro di cacao dal gusto ricco e lussuoso.'),
  ('20000000-0000-0000-0000-000000000002', 'ar', 'كوكيز المكسرات الغنية', 'كوكيز جولد غنية بالجوز والكاجو والبندق والفستق، محمصة بعناية لتقدم مذاقًا فاخرًا في كل قطعة.'),
  ('20000000-0000-0000-0000-000000000002', 'en', 'Rich Nut Cookies', 'Gold cookies where nuts are the star, with walnuts, cashews, hazelnuts, and pistachios delivering a luxurious roasted taste.'),
  ('20000000-0000-0000-0000-000000000002', 'it', 'Biscotti ricchi di frutta secca', 'Biscotti Gold con noci, anacardi, nocciole e pistacchi tostati per un gusto ricco e lussuoso.'),
  ('20000000-0000-0000-0000-000000000003', 'ar', 'كوكيز التوت البري الطبيعي', 'كوكيز جولد بنكهة فاكهية راقية تجمع بين الانتعاش والحلاوة، محضرة بدقيق الشعير الكامل والزبدة.'),
  ('20000000-0000-0000-0000-000000000003', 'en', 'Natural Cranberry Cookies', 'Gold cranberry cookies with a refined fruity flavor that combines freshness and sweetness, made with whole barley flour and butter.'),
  ('20000000-0000-0000-0000-000000000003', 'it', 'Biscotti naturali ai mirtilli rossi', 'Biscotti Gold ai mirtilli rossi dal gusto fruttato, preparati con farina integrale d’orzo e burro.'),
  ('20000000-0000-0000-0000-000000000004', 'ar', 'معمول المكسرات الفاخر', 'معمول جولد بحشوة سخية من الجوز والفستق، بقطع تذوب في الفم ومذاق غني مناسب للضيافة والهدايا.'),
  ('20000000-0000-0000-0000-000000000004', 'en', 'Luxury Nut Maamoul', 'Luxury Gold Maamoul with a generous walnut and pistachio filling, made for hospitality and gifting.'),
  ('20000000-0000-0000-0000-000000000004', 'it', 'Maamoul di lusso alla frutta secca', 'Maamoul Gold con abbondante ripieno di noci e pistacchi, perfetto per l’ospitalità e i regali.'),
  ('20000000-0000-0000-0000-000000000005', 'ar', 'ميكس لونا جولد', 'تجربة لونا جولد الكاملة في علبة أنيقة جاهزة للإهداء، تجمع بين كوكيز الشوكولاتة والمكسرات الفاخرة.'),
  ('20000000-0000-0000-0000-000000000005', 'en', 'Luna Gold Mix', 'The complete Luna Gold experience in an elegant gift-ready box with double chocolate and double nut cookies.'),
  ('20000000-0000-0000-0000-000000000005', 'it', 'Mix Luna Gold', 'L’esperienza completa Luna Gold in una confezione elegante con biscotti al doppio cioccolato e alla doppia frutta secca.'),
  ('20000000-0000-0000-0000-000000000006', 'ar', 'كوكيز الشوكولاتة', 'كوكيز مخبوزة بعناية بنكهة شوكولاتة لونا الغنية، بمذاق عميق يرضي محبي الشوكولاتة من أول قضمة.'),
  ('20000000-0000-0000-0000-000000000006', 'en', 'Chocolate Cookies', 'Carefully baked cookies with rich Luna chocolate flavor and a deep taste that satisfies chocolate lovers.'),
  ('20000000-0000-0000-0000-000000000006', 'it', 'Biscotti al cioccolato', 'Biscotti preparati con il ricco gusto del cioccolato Luna, dal sapore intenso per gli amanti del cioccolato.'),
  ('20000000-0000-0000-0000-000000000007', 'ar', 'كوكيز المكسرات', 'كوكيز بالجوز والكاجو المحمصين، مع دقيق الشعير الكامل والزبدة وتحلية طبيعية بدون سكر مكرر.'),
  ('20000000-0000-0000-0000-000000000007', 'en', 'Nut Cookies', 'Cookies made with roasted walnuts and cashews, whole barley flour, natural butter, and natural molasses.'),
  ('20000000-0000-0000-0000-000000000007', 'it', 'Biscotti alla frutta secca', 'Biscotti con noci e anacardi tostati, farina integrale d’orzo, burro naturale e melassa naturale.'),
  ('20000000-0000-0000-0000-000000000008', 'ar', 'معمول التمر مع بسكويت لونا المتبل', 'معمول لونا بحشوة تمر غنية وقوام ناعم، مع بسكويت لونا المتبل بالقرفة والتوابل.'),
  ('20000000-0000-0000-0000-000000000008', 'en', 'Date Maamoul with Luna Spiced Biscuits', 'Luna Date Maamoul with a rich date filling and soft texture, paired with warm spiced biscuits.'),
  ('20000000-0000-0000-0000-000000000008', 'it', 'Maamoul ai datteri con biscotti speziati Luna', 'Maamoul Luna con ricco ripieno di datteri e biscotti speziati alla cannella.'),
  ('20000000-0000-0000-0000-000000000009', 'ar', 'كوكيز الفواكه المجففة', 'كوكيز بنكهة فاكهية مميزة مع قطع المشمش والتين والبرقوق المجففة ودقيق الشعير.'),
  ('20000000-0000-0000-0000-000000000009', 'en', 'Dried Fruit Cookies', 'Cookies with a warm fruity flavor and naturally dried apricot, fig, and prune pieces with barley flour.'),
  ('20000000-0000-0000-0000-000000000009', 'it', 'Biscotti alla frutta disidratata', 'Biscotti dal gusto fruttato con albicocca, fico e prugna disidratati e farina d’orzo.'),
  ('20000000-0000-0000-0000-000000000010', 'ar', 'علبة ميكس كلاسيك', 'كل نكهات لونا كلاسيك في علبة واحدة: الشوكولاتة والمكسرات والفواكه المجففة.'),
  ('20000000-0000-0000-0000-000000000010', 'en', 'Classic Mix Box', 'All Luna Classic flavors in one box: rich chocolate, walnut and cashew, and natural dried fruit cookies.'),
  ('20000000-0000-0000-0000-000000000010', 'it', 'Box Mix Classico', 'Tutti i gusti Luna Classic in una confezione: cioccolato, noci e anacardi e frutta disidratata.'),
  ('20000000-0000-0000-0000-000000000011', 'ar', 'ميكس الشوكولاتة واللوز المقرمش', 'علبة كوكيز لونا كلاسيك بالشوكولاتة مع علبة كوكيز اللوز المحمص المقرمش.'),
  ('20000000-0000-0000-0000-000000000011', 'en', 'Chocolate and Almond Crunch', 'Luna Classic chocolate cookies paired with a pack of crispy roasted almond cookies.'),
  ('20000000-0000-0000-0000-000000000011', 'it', 'Mix croccante al cioccolato e mandorle', 'Biscotti Luna Classic al cioccolato abbinati a biscotti croccanti alle mandorle tostate.'),
  ('20000000-0000-0000-0000-000000000012', 'ar', 'بسكويت لونا المتبل', 'بسكويت خفيف ومقرمش بنكهة القرفة الطبيعية ومحلى بدبس التمر والعسل الأسود بدون إضافات صناعية.'),
  ('20000000-0000-0000-0000-000000000012', 'en', 'Luna Spiced Biscuits', 'Light and crispy biscuits with natural Ceylon cinnamon, date molasses, and black honey.'),
  ('20000000-0000-0000-0000-000000000012', 'it', 'Biscotti speziati Luna', 'Biscotti leggeri e croccanti con cannella naturale, melassa di datteri e miele nero.'),
  ('20000000-0000-0000-0000-000000000013', 'ar', 'ميني وكرانش', 'علبة لونا ميني مع قطعتين من كوكيز لونا وعبوة من كوكيز اللوز المحمص المقرمش.'),
  ('20000000-0000-0000-0000-000000000013', 'en', 'Mini & Crunch', 'A Luna Mini box with two rich Luna cookies and a pack of crunchy toasted almond cookies.'),
  ('20000000-0000-0000-0000-000000000013', 'it', 'Mini & Crunch', 'Una box Luna Mini con due biscotti Luna e una confezione di biscotti croccanti alle mandorle.'),
  ('20000000-0000-0000-0000-000000000014', 'ar', 'ميكس لونا - قطعتان', 'قطعتان من كوكيز الشوكولاتة الغنية وكوكيز المكسرات المحمصة من لونا.'),
  ('20000000-0000-0000-0000-000000000014', 'en', 'Luna Mix - 2 Pieces', 'Two pieces of Luna rich chocolate cookies and roasted nut cookies.'),
  ('20000000-0000-0000-0000-000000000014', 'it', 'Mix Luna - 2 pezzi', 'Due biscotti Luna al cioccolato e alla frutta secca tostata.'),
  ('20000000-0000-0000-0000-000000000015', 'ar', 'ميكس لونا - 4 قطع', 'أربع قطع من أشهر نكهات لونا: كوكيز الشوكولاتة الغنية وكوكيز المكسرات المحمصة.'),
  ('20000000-0000-0000-0000-000000000015', 'en', 'Luna Mix - 4 Pieces', 'Four pieces of Luna’s most popular rich chocolate and roasted nut cookies.'),
  ('20000000-0000-0000-0000-000000000015', 'it', 'Mix Luna - 4 pezzi', 'Quattro biscotti Luna ai gusti più amati: cioccolato ricco e frutta secca tostata.')
